actions.script:
import org.moqui.context.ExecutionContext
ExecutionContext ec = context.ec
def fromD = (fromDate ?: ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd'))
def thruD = (thruDate ?: fromD)
def ds = java.sql.Timestamp.valueOf(fromD + ' 00:00:00')
def de = java.sql.Timestamp.valueOf(thruD + ' 23:59:59')
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def billStatuses = ['PtCompleted','PtVoided','PtReturned','PtCancelled','PtReversed']
def f = ec.entity.find("zenith.erp.pos.PosTransactionView")
    .condition("entryDate","greater-equals",ds).condition("entryDate","less-equals",de)
if (statusId) f.condition("statusId", statusId) else f.condition("statusId","in",billStatuses)
if (_org) f.condition("organizationPartyId", _org)
def userMap = new LinkedHashMap()
f.list().each { t ->
    def opId = t.operatorPartyId ?: 'Unknown'
    if (!userMap[opId]) {
        def p = opId != 'Unknown' ? ec.entity.find("mantle.party.Person").condition("partyId", opId).one() : null
        def nm = p ? "${p.firstName ?: ''} ${p.lastName ?: ''}".trim() : opId
        userMap[opId] = [name:nm, sales:0.0G, disc:0.0G, bills:0, last:null]
    }
    def u = userMap[opId]
    u.sales += (t.payableAmount ?: 0) as BigDecimal
    u.disc  += (t.discountTotal ?: 0) as BigDecimal
    u.bills++
    if (t.entryDate != null && (u.last == null || t.entryDate > u.last)) u.last = t.entryDate
}
def rows = userMap.values().sort { -(it.sales as BigDecimal) }
def st = (searchText ?: '').trim().toLowerCase()
if (st) rows = rows.findAll { (it.name ?: '').toLowerCase().contains(st) }
def esc = { v -> if (v == null) return ""; String s = v.toString().trim(); (s.contains(",")||s.contains("\"")||s.contains("\n")) ? "\"" + s.replace("\"","\"\"") + "\"" : s }
def num = { v -> String.format("%.2f", (v ?: 0.0) as double) }
def dt = { v -> v == null ? "" : ec.l10n.format(v, 'yyyy-MM-dd hh:mm a') }
StringBuilder csv = new StringBuilder()
csv.append("ZetaERP - User Wise Report\n")
csv.append("Period: ${fromD} to ${thruD}  |  Generated: ${ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')}\n\n")
csv.append("User Name,Total Bills,Total Sales,Total Discounts,Net Sales,Avg Bill Value,Last Active\n")
rows.each { u ->
    def avg = u.bills > 0 ? (u.sales / u.bills) : 0.0G
    csv.append("${esc(u.name)},${u.bills},${num(u.sales)},${num(u.disc)},${num(u.sales - u.disc)},${num(avg)},${dt(u.last)}\n")
}
ec.web.sendTextResponse(csv.toString(), "text/csv", "User_Wise_${ec.l10n.format(ec.user.nowTimestamp, 'yyyyMMdd_HHmm')}.csv")

def zinr = context.zinr
// ZE-SALES-014 f/u: org-isolate (standalone CSV/PDF render skips the authz filter)
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def billStatuses = ['PtCompleted','PtVoided','PtReturned','PtCancelled','PtReversed']
def _txnFind = ec.entity.find("zenith.erp.pos.PosTransactionView")
    .condition("entryDate", "greater-equals", dayStart)
    .condition("entryDate", "less-equals", dayEnd)
if (statusId) _txnFind.condition("statusId", statusId)
else _txnFind.condition("statusId", "in", billStatuses)
if (_org) _txnFind.condition("organizationPartyId", _org)
def txns = _txnFind.list()

def userMap = new LinkedHashMap()
txns.each { t ->
    def opId = t.operatorPartyId ?: 'Unknown'
    if (!userMap[opId]) {
        def person = opId != 'Unknown' ? ec.entity.find("mantle.party.Person").condition("partyId", opId).one() : null
        def name = person ? "${person.firstName ?: ''} ${person.lastName ?: ''}".trim() : opId
        userMap[opId] = [operatorId: opId, operatorName: (name ?: opId), totalSales: BigDecimal.ZERO,
            billCount: 0 as int, totalDiscount: BigDecimal.ZERO, netSales: BigDecimal.ZERO,
            avgBill: BigDecimal.ZERO, lastActive: null]
    }
    def u = userMap[opId]
    u.totalSales += (t.payableAmount ?: 0) as BigDecimal
    u.totalDiscount += (t.discountTotal ?: 0) as BigDecimal
    u.billCount++
    if (t.entryDate != null && (u.lastActive == null || t.entryDate > u.lastActive)) u.lastActive = t.entryDate
}
userMap.values().each { u ->
    if (u.billCount > 0) u.avgBill = (u.totalSales / u.billCount).setScale(2, java.math.RoundingMode.HALF_UP)
    u.netSales = (u.totalSales - u.totalDiscount)
}
def rows = userMap.values().sort { -(it.totalSales as BigDecimal) }
def st = (searchText ?: '').trim().toLowerCase()
if (st) rows = rows.findAll { (it.operatorName ?: '').toLowerCase().contains(st) }
userWiseList = rows

// Stat-card totals
statTotalUsers = userWiseList.size()
statTotalBills = userWiseList.sum { it.billCount } ?: 0
def sumSales = userWiseList.inject(0.0G) { a, it -> a + (it.totalSales as BigDecimal) }
def sumDisc  = userWiseList.inject(0.0G) { a, it -> a + (it.totalDiscount as BigDecimal) }
statTotalSalesStr = '₹ ' + zinr.inr(ec.l10n.format(sumSales, '#,##0.00'))
statTotalDiscStr  = '₹ ' + zinr.inr(ec.l10n.format(sumDisc, '#,##0.00'))

row-actions.script:
def z = zinr ?: com.zenith.Fmt.INSTANCE
def money = { v -> z.inr(ec.l10n.format((v ?: 0) as BigDecimal, '#,##0.00')) }
def nm = (u.operatorName ?: '').trim()
def parts = nm ? nm.split(/\s+/) : ([] as String[])
if (parts.length >= 2) initials = (parts[0][0].toString() + parts[1][0].toString()).toUpperCase()
else if (nm.length() >= 2) initials = nm.substring(0,2).toUpperCase()
else if (nm.length() == 1) initials = nm.toUpperCase()
else initials = '?'
salesDisp = money(u.totalSales)
discDisp  = money(u.totalDiscount)
netDisp   = money(u.netSales)
avgDisp   = money(u.avgBill)
lastDisp  = u.lastActive ? ec.l10n.format(u.lastActive, 'yyyy-MM-dd hh:mm a') : '—'
